import { PDFDocument } from "pdf-lib";
import sharp from "sharp";
import QRCode from "qrcode";
const mm = (n: number) => (n * 72) / 25.4;

/** A QR label is a way to open a receipt, not a substitute receipt generated by the shop. */
export async function qrLabelPdf(url: string, kind: "hello" | "receipt") {
  const qr = await QRCode.toBuffer(url, {
    width: 320,
    margin: 4,
    errorCorrectionLevel: "M",
  });
  const heading = kind === "hello" ? "Давайте не потеряемся" : "Ваш чек ФНС";
  const sub = kind === "hello" ? "Керамика и чудики" : "Наведите камеру";
  // Cyrillic is rasterized by the system font renderer before embedding.
  const text = Buffer.from(
    `<svg width="400" height="580"><rect width="400" height="580" fill="white"/><g text-anchor="middle" fill="#000" font-family="Arial, sans-serif"><text x="200" y="60" font-size="42" font-weight="bold">roota</text><text x="200" y="104" font-size="19">${heading}</text><text x="200" y="475" font-size="20">${sub}</text><text x="200" y="515" font-size="18">roota.moscow</text></g></svg>`,
  );
  const image = await sharp(text)
    .composite([{ input: qr, left: 40, top: 135 }])
    .png()
    .toBuffer();
  const doc = await PDFDocument.create();
  doc.setTitle(
    kind === "hello" ? "Roota · знакомство" : "Roota · ссылка на чек ФНС",
  );
  const page = doc.addPage([mm(40), mm(58)]);
  const embedded = await doc.embedPng(image);
  page.drawImage(embedded, { x: 0, y: 0, width: mm(40), height: mm(58) });
  return Buffer.from(await doc.save());
}
export async function officialReceiptPdf(
  bytes: Uint8Array,
  contentType: string,
) {
  if (contentType.includes("application/pdf")) {
    // Parse before returning to ensure the response really is a PDF.
    await PDFDocument.load(bytes);
    return Buffer.from(bytes);
  }
  if (!/^image\/(png|jpeg|webp)/i.test(contentType))
    throw new Error(
      "ФНС не вернула изображение чека. Откройте официальный чек и сохраните его через окно печати",
    );
  const image = await sharp(bytes, { limitInputPixels: 40000000 })
    .flatten({ background: "#fff" })
    .png()
    .toBuffer();
  const doc = await PDFDocument.create();
  doc.setTitle("Чек ФНС · исходное изображение");
  const embedded = await doc.embedPng(image);
  const page = doc.addPage([595.28, 841.89]);
  const fit = embedded.scaleToFit(page.getWidth() - 40, page.getHeight() - 40);
  page.drawImage(embedded, {
    x: (page.getWidth() - fit.width) / 2,
    y: page.getHeight() - 20 - fit.height,
    ...fit,
  });
  return Buffer.from(await doc.save());
}
